#!/usr/bin/env python3
import argparse, json
from pathlib import Path

def load(path):
    with Path(path).open(encoding="utf-8") as fh:
        return json.load(fh)

def matches(rule, flow):
    return (rule.get("src_zone")==flow.get("src_zone") and rule.get("dst_zone")==flow.get("dst_zone")
            and rule.get("protocol")==flow.get("protocol") and int(rule.get("dst_port"))==int(flow.get("dst_port")))

def main():
    ap=argparse.ArgumentParser(description="Offline network-policy validator")
    ap.add_argument("rules"); ap.add_argument("flows")
    args=ap.parse_args()
    rules=load(args.rules).get("rules"); flows=load(args.flows)
    if not isinstance(rules,list) or not isinstance(flows,list):
        raise ValueError("Invalid input structure")
    findings=[f for f in flows if not any(matches(r,f) for r in rules)]
    print(json.dumps({"flow_count":len(flows),"uncovered_count":len(findings),"findings":findings},indent=2))

if __name__=="__main__": main()
